sealed class CampaignEngine {
 readonly TrainerSession session;readonly string root;public readonly List<CampaignAction> Actions;public readonly Dictionary<string,List<CatalogItem>> Catalogs;
 readonly HashSet<string> caches=new HashSet<string>();public readonly List<string> History=new List<string>();public bool Busy;public readonly CampaignStories Stories;
 public CampaignEngine(TrainerSession session,string root){this.session=session;this.root=root;var j=new JavaScriptSerializer{MaxJsonLength=30000000};Actions=j.Deserialize<List<CampaignAction>>(File.ReadAllText(Path.Combine(root,"campaign-actions.json")));Catalogs=j.Deserialize<Dictionary<string,List<CatalogItem>>>(File.ReadAllText(Path.Combine(root,"campaign-catalogues.json")));Lang.Localize(Actions);Lang.Localize(Catalogs);Stories=new CampaignStories(session,this);}
 public static string Quote(string value){value=(value??"").Trim();if(value.Length>250 || value.Any(c=>Char.IsControl(c) || "{}\"\\$[]".Contains(c)))throw new InvalidOperationException(Lang.T("Текст: до 250 символов, без скобок, кавычек и служебных знаков."));return "\""+value+"\"";}
 public static string Key(string value){if(!Regex.IsMatch(value??"","^[A-Za-z0-9_-]+$"))throw new InvalidOperationException(Lang.T("Выбери корректный ID из справочника."));return value;}
 async Task<EngineReply> SendText(string body,uint id,CampaignParameters p){try{return await session.Send(body,id);}catch(InvalidOperationException){string raw=session.LastReply;var errors=EngineReply.CommandErrors(raw);if(!raw.Contains("console_failure:") && errors.Count>0 && errors.All(l=>l.Contains("jomini_dynamicdescription.cpp:453") && new[]{p.Text,p.Text2}.Where(t=>!String.IsNullOrEmpty(t)).Any(t=>l.Contains("Unrecognized loc key "+t+". file: effect console command"))))return new EngineReply(raw,false);throw;}}
 void Check(){session.Bridge.Refresh();if(session.State==null || session.State.Player!=session.Bridge.PlayerID || session.State.PlayerPointer!=session.Bridge.PlayerPointer)throw new InvalidOperationException(Lang.T("Кампания или игрок сменились. Закрой редактор и обнови подключение."));}
 public static readonly Dictionary<string,string> Iterators=new Dictionary<string,string>{{"faction","every_targeting_faction"},{"person","every_child"},{"war","every_character_war"},{"regiment","every_maa_regiment"},{"artifact","every_character_artifact"},{"scheme","every_scheme"},{"targeting_scheme","every_targeting_scheme"},{"secret","every_known_secret"},{"contract","every_character_active_contract"},{"title","every_sub_realm_title"},{"army","every_army"}};
 public async Task<List<CampaignObject>> Collect(string kind,uint owner){Check();if(!session.Bridge.ValidCharacter(owner))throw new InvalidOperationException(Lang.T("Внутренний ID владельца не существует."));if(!Iterators.ContainsKey(kind))throw new InvalidOperationException(Lang.T("Неизвестный тип объекта."));
  string cache="ck3t_v3_cache_"+kind;caches.Add(cache);
  string body="clear_global_variable_list = "+cache+" add_to_global_variable_list = { name = "+cache+" target = this } remove_list_global_variable = { name = "+cache+" target = this } "+Iterators[kind]+" = { add_to_global_variable_list = { name = "+cache+" target = this } debug_log = \"CK3T_V3_OBJECT\" debug_log_scopes = no }";
  var r=await session.Send(body,owner);var objects=ParseObjects(r.Text,kind,cache);foreach(var o in objects)o.Character=owner;return objects;
 }
 public static List<CampaignObject> ParseObjects(string text,string kind,string cache,string marker="CK3T_V3_OBJECT"){var result=new List<CampaignObject>();bool awaiting=false;foreach(string line in text.Split('\n')){
  if(line.Contains("jomini_effect_impl.cpp") && line.Contains(marker)){awaiting=true;continue;}if(!awaiting || !line.Contains("effectimpl.cpp:642"))continue;
  var m=Regex.Match(line,@"\]: (.*?) \(Internal ID: '?([0-9]+)'?(.*?)\) .*?\(([^()]+)\s*[—-]\s*\d+\)");if(!m.Success)continue;
  string type=m.Groups[4].Value.Trim().ToLowerInvariant();string expected=kind=="person"?"character":kind=="title"?"landed_title":kind=="targeting_scheme"?"scheme":kind=="contract"?"task_contract":kind;
  if(type.Replace(" ","_")!=expected)continue;var key=Regex.Match(m.Groups[3].Value,@"Internal Key: ([a-zA-Z0-9_-]+)");result.Add(new CampaignObject{Kind=kind,Cache=cache,Position=result.Count,Name=Regex.Replace(m.Groups[1].Value,@"\x15[^\x15]*\x15","").Trim(),Identity=m.Groups[2].Value,Key=key.Success?key.Groups[1].Value:""});awaiting=false;
 }return result;}
 public Task<List<Person>> SearchPeople(string skill,int minimum,bool unmarried,bool sameFaith){return SearchPeople(new PeopleCriteria{Skill=skill,Minimum=minimum,Unmarried=unmarried,SameFaith=sameFaith});}
 public async Task<List<Person>> SearchPeople(PeopleCriteria p){Check();if(!new[]{"diplomacy","martial","stewardship","intrigue","learning","prowess"}.Contains(p.Skill) || p.Minimum<0 || p.Minimum>1000 || p.MinAge<18 || p.MaxAge<p.MinAge || p.MaxAge>150 || !new[]{"any","male","female"}.Contains(p.Gender))throw new InvalidOperationException(Lang.T("Проверь навык, возраст и пол кандидатов."));foreach(string t in p.Traits)if(!Catalogs["trait"].Any(x=>x.id==Key(t)))throw new InvalidOperationException(Lang.T("Неизвестная черта."));if(!String.IsNullOrEmpty(p.Claim) && !Catalogs["title"].Any(x=>x.id==Key(p.Claim)))throw new InvalidOperationException(Lang.T("Неизвестный титул претензии."));string filter="is_alive = yes age >= "+p.MinAge+" age <= "+p.MaxAge+" "+p.Skill+" >= "+p.Minimum+(p.Unmarried?" is_married = no":"")+(p.SameFaith?" faith = global_var:ck3t_v3_player.faith":"")+(p.Gender=="any"?"":" is_female = "+(p.Gender=="female"?"yes":"no"))+(p.Alliance?" OR = { is_ruler = yes AND = { exists = father father = { is_ruler = yes } } AND = { exists = mother mother = { is_ruler = yes } } }":"")+(String.IsNullOrEmpty(p.Claim)?"":" has_claim_on = title:"+p.Claim)+" "+String.Join(" ",p.Traits.Select(t=>"has_trait = "+t));string body="set_global_variable = { name = ck3t_v3_player value = this } ordered_living_character = { limit = { "+filter+" } order_by = "+p.Skill+" max = 100 check_range_bounds = no debug_log = \"CK3T_V3_OBJECT\" debug_log_scopes = no } remove_global_variable = ck3t_v3_player";var r=await session.Send(body,session.State.Player);return ParseObjects(r.Text,"person","").Select(o=>new Person{ID=UInt32.Parse(o.Identity),Name=o.Name,Role="Поиск: "+p.Skill}).ToList();}
 async Task Resolve(CampaignObject obj,uint actor){if(obj!=null && obj.Character!=0 && obj.Character!=actor)throw new InvalidOperationException(Lang.T("Список принадлежит другому персонажу. Прочитай объекты заново."));if(obj==null)throw new InvalidOperationException(Lang.T("Сначала прочитай объекты и выбери один."));if(!caches.Contains(obj.Cache))throw new InvalidOperationException(Lang.T("Список объектов устарел."));string cmd="remove_global_variable = ck3t_v3_selected ordered_in_global_list = { variable = "+obj.Cache+" position = "+obj.Position+" check_range_bounds = no set_global_variable = { name = ck3t_v3_selected value = this } debug_log = \"CK3T_V3_OBJECT\" debug_log_scopes = no }";var r=await session.Send(cmd,actor);var actual=ParseObjects(r.Text,obj.Kind,obj.Cache);if(actual.Count!=1 || actual[0].Identity!=obj.Identity)throw new InvalidOperationException(Lang.T("Объект изменился или исчез. Обнови список перед действием."));var member=await session.Send(Iterators[obj.Kind]+" = { limit = { this = global_var:ck3t_v3_selected } debug_log = \"CK3T_MEMBER_OK\" }",actor);if(!member.Rows("CK3T_MEMBER_OK").Any())throw new InvalidOperationException(Lang.T("Объект больше не принадлежит выбранному персонажу. Обнови список."));}
 public string Expand(CampaignAction a,CampaignParameters p){
  foreach(var pair in new[]{new[]{a.arg,p.Arg},new[]{a.arg2,p.Arg2}})if(!String.IsNullOrEmpty(pair[0])){if(!Catalogs.ContainsKey(pair[0]) || !Catalogs[pair[0]].Any(x=>x.id==pair[1]))throw new InvalidOperationException(Lang.T("Выбери параметр из справочника: ")+pair[0]);Key(pair[1]);}
  if(p.Value<a.min || a.max!=0 && p.Value>a.max)throw new InvalidOperationException(Lang.T("Значение вне диапазона ")+a.min+"–"+a.max+".");
  string template=ExpandChoices(a.body,p).Replace("$OLD_SIZE",p.OldSize.ToString()).Replace("$OLD_TROOPS",p.OldTroops.ToString());int recipients;while((recipients=template.IndexOf("$RECIPIENTS{",StringComparison.Ordinal))>=0){int depth=1,end=recipients+12;for(;end<template.Length && depth>0;end++){if(template[end]=='{')depth++;if(template[end]=='}')depth--;}if(depth!=0 || p.Recipients.Count<1 || p.Recipients.Count>20)throw new InvalidOperationException(Lang.T("Укажи 1–20 получателей."));string inner=template.Substring(recipients+12,end-recipients-13);template=template.Substring(0,recipients)+String.Join(" ",Enumerable.Range(0,p.Recipients.Count).Select(i=>"global_var:ck3t_v3_recipient_"+i+" = { "+inner+" }"))+template.Substring(end);}int distribute;while((distribute=template.IndexOf("$DISTRIBUTE{",StringComparison.Ordinal))>=0){int depth=1,end=distribute+12;for(;end<template.Length && depth>0;end++){if(template[end]=='{')depth++;if(template[end]=='}')depth--;}if(depth!=0)throw new InvalidOperationException(Lang.T("Незакрытый шаблон распределения."));if(p.Recipients.Count<1 || p.Recipients.Count>20 || p.Titles.Count<1 || p.Titles.Count>100)throw new InvalidOperationException(Lang.T("Распределение: 1–20 получателей и 1–100 титулов."));string inner=template.Substring(distribute+12,end-distribute-13);template=template.Substring(0,distribute)+String.Join(" ",p.Titles.Select((t,i)=>"title:"+Key(t)+" = { "+inner.Replace("$RECIPIENT","global_var:ck3t_v3_recipient_"+(i%p.Recipients.Count))+" }"))+template.Substring(end);}int at;while((at=template.IndexOf("$TITLES{",StringComparison.Ordinal))>=0){int depth=1,end=at+8;for(;end<template.Length && depth>0;end++){if(template[end]=='{')depth++;if(template[end]=='}')depth--;}if(depth!=0)throw new InvalidOperationException(Lang.T("Незакрытый шаблон земель."));string inner=template.Substring(at+8,end-at-9);if(p.Titles==null || p.Titles.Count==0)throw new InvalidOperationException(Lang.T("Выбери земли."));if(p.Titles.Count>100)throw new InvalidOperationException(Lang.T("За одну операцию можно отметить до 100 титулов."));foreach(string t in p.Titles)if(!Catalogs["title"].Any(x=>x.id==Key(t)))throw new InvalidOperationException(Lang.T("Неизвестный титул: ")+t);template=template.Substring(0,at)+String.Join(" ",p.Titles.Distinct().Select(t=>"title:"+t+" = { "+inner+" }"))+template.Substring(end);}
  string body=template.Replace("$ARG2",p.Arg2??"").Replace("$ARG",p.Arg??"").Replace("$TEXT2",Quote(p.Text2)).Replace("$TEXT",Quote(p.Text)).Replace("$TITLE2","title:"+Key(String.IsNullOrEmpty(p.Title2)?"c_roma":p.Title2)).Replace("$TITLE","title:"+Key(String.IsNullOrEmpty(p.Title)?"c_roma":p.Title)).Replace("$PROVINCE","province:"+p.Province).Replace("$VALUE2",p.Value2.ToString()).Replace("$VALUE",p.Value.ToString()).Replace("$OTHER","global_var:ck3t_v3_other").Replace("$PLAYER","global_var:ck3t_v3_player").Replace("$SELF","global_var:ck3t_v3_actor").Replace("$OBJECT","global_var:ck3t_v3_selected").Replace("$DIRTY",Templates.Dirty);
  body=Templates.Expand(body,"ck3t_v3_player");if(body.Contains("$"))throw new InvalidOperationException(Lang.T("Необработанный параметр команды."));return body;
 }
 string ExpandChoices(string template,CampaignParameters p){var macros=new Dictionary<string,string[]>{{"$TRAITS",new[]{"trait","trait = "}},{"$TENETS",new[]{"tenet","core_tenet_override_entry = tenet:"}},{"$DOCTRINES",new[]{"doctrine","doctrine_override_entry = doctrine:"}},{"$MODIFIERS",new[]{"artifact_modifier","modifier = "}},{"$TRADITIONS",new[]{"tradition","add_culture_tradition = "}}};foreach(var macro in macros){if(!template.Contains(macro.Key))continue;List<string> chosen;if(!p.Choices.TryGetValue(macro.Value[0],out chosen))chosen=new List<string>();if(chosen.Count>50 || macro.Key=="$TENETS" && chosen.Count>3)throw new InvalidOperationException(Lang.T("Слишком много выбранных параметров: ")+macro.Value[0]);if(macro.Key=="$MODIFIERS" && chosen.Count==0)throw new InvalidOperationException(Lang.T("Артефакту нужен хотя бы один бонус."));foreach(string item in chosen)if(!Catalogs[macro.Value[0]].Any(x=>x.id==Key(item)))throw new InvalidOperationException(Lang.T("Неизвестный параметр: ")+item);if(macro.Key=="$DOCTRINES"){var groups=chosen.Select(k=>Catalogs["doctrine"].First(x=>x.id==k).group).Where(g=>!String.IsNullOrEmpty(g)).GroupBy(g=>g);if(groups.Any(g=>g.Count()>1))throw new InvalidOperationException(Lang.T("В каждой категории нужна одна доктрина: ")+groups.First(g=>g.Count()>1).Key);}template=template.Replace(macro.Key,String.Join(" ",chosen.Distinct().Select(x=>macro.Value[1]+x)));}if(template.Contains("$STATS")){if(p.Stats==null || p.Stats.Length!=6 || p.Stats.Any(x=>x<0 || x>1000))throw new InvalidOperationException(Lang.T("Каждый из шести навыков: 0–1000."));var names=new[]{"diplomacy","martial","stewardship","intrigue","learning","prowess"};template=template.Replace("$STATS",String.Join(" ",Enumerable.Range(0,6).Select(i=>names[i]+" = "+p.Stats[i])));}return template;}
 async Task CheckScenarioEligibility(CampaignAction a,uint actor){if(!a.scenario)return;string conditions="";switch(a.id){case "scenario_council":conditions="is_landed = yes exists = primary_title";break;case "scenario_split":case "scenario_last_king":conditions="is_landed = yes exists = primary_title";break;case "scenario_academy":conditions="exists = house";break;case "scenario_tournament":conditions="exists = house can_designate_heir_trigger = yes any_child = { is_alive = yes age >= 18 }";break;}if(conditions=="")return;var reply=await session.Send("if = { limit = { "+conditions+" } debug_log = \"CK3T_SCENARIO_ELIGIBLE\" }",actor);if(!reply.Rows("CK3T_SCENARIO_ELIGIBLE").Any())throw new InvalidOperationException(Lang.T("Сценарий сейчас недоступен персонажу: проверь землю, дом, взрослых детей и закон наследования."));}
 public async Task<CampaignPlan> Prepare(CampaignAction a,CampaignParameters p){Check();if(a.pack && !session.PackV2)throw new InvalidOperationException(Lang.T("Сначала загрузите установленный пакет ручным перезапуском CK3."));if(p.Character==0)p.Character=session.State.Player;var actor=await session.Inspect(p.Character);await CheckScenarioEligibility(a,p.Character);Person other=null;if(a.other){if(p.Other==0 || p.Other==p.Character && a.id!="copy_appearance")throw new InvalidOperationException(Lang.T("Выбери другого персонажа."));other=await session.Inspect(p.Other);}
  if(a.body.Contains("$PROVINCE") && p.Province==0)throw new InvalidOperationException(Lang.T("Нужен ID провинции."));if(a.scope!="character" && a.scope!="province" && a.scope!="faith" && a.scope!="culture" && a.scope!="domicile" && a.scope!="title_key")await Resolve(p.Object,p.Character);
  if(a.id=="succession_order" || a.id=="scenario_split"){var children=await Collect("person",p.Character);if(p.Recipients.Any(id=>!children.Any(c=>c.Identity==id.ToString())))throw new InvalidOperationException(Lang.T("В порядке наследников и расколе выбирай прямых детей первого персонажа."));}var recipientNames=new List<string>();if(a.recipients){if(p.Recipients.Count<1 || p.Recipients.Count>20 || p.Recipients.Distinct().Count()!=p.Recipients.Count)throw new InvalidOperationException(Lang.T("Укажи 1–20 разных ID получателей в нужном порядке."));foreach(uint id in p.Recipients){if(!session.Bridge.LivingCharacter(id))throw new InvalidOperationException(Lang.T("Получатель должен быть жив: ")+id);var person=await session.Inspect(id);recipientNames.Add(person.Name+" ["+id+"]");}}if(a.body.Contains("$OLD_SIZE")){var stats=await RegimentStats(p.Character);p.OldSize=stats[0];p.OldTroops=stats[1];}if(a.id=="finish_selected_construction" && p.Province==0)throw new InvalidOperationException(Lang.T("Укажи ID провинции."));List<ConstructionRecord> construction=null;string body;if(a.native=="construction"){construction=await ReadConstructions(p.Character,a.id=="finish_selected_construction"?p.Province:0);if(construction.Count==0)throw new InvalidOperationException(Lang.T("В выбранном охвате нет текущих строек."));body=String.Join(" ",construction.Select(r=>"province:"+r.Province+" = { "+(r.Key.EndsWith("_holding")?"create_holding = ":"add_building = ")+r.Key+" debug_log = \"CK3T_CONSTRUCTION_DONE\" }"));}else body=Expand(a,p);string preview=a.title+Lang.T("\r\n\r\nИсполнитель: ")+actor.Name+" ["+actor.ID+"]"+(other!=null?Lang.T("\r\nВторой персонаж: ")+other.Name+" ["+other.ID+"]":"")+(p.Object!=null?Lang.T("\r\nОбъект: ")+p.Object:"")+(a.body.Contains("$OLD_SIZE")?Lang.T("\r\nРазмер: ")+p.OldSize+Lang.T(" · бойцов: ")+p.OldTroops:"")+(Regex.IsMatch(a.body,@"\$TITLE")?Lang.T("\r\nТитул: ")+p.Title+Lang.T("\r\nВторой титул: ")+p.Title2:"")+"\r\n\r\n"+a.description+Lang.T("\r\n\r\nОхват территории: ")+(Templates.Realm?Lang.T("держава с вассалами"):Lang.T("личный домен"))+(a.readOnly?Lang.T("\r\nЧтение данных, игровые свойства сохраняются."):a.native=="war_score" || a.native=="war_score_reset" || a.native=="culture_head" || a.native=="culture_head_reset"?Lang.T("\r\nНативное назначение действует до снятия в приложении."):Lang.T("\r\nПостоянные изменения останутся в сохранении."));
  if(Encoding.UTF8.GetByteCount(body)>43000)throw new InvalidOperationException(Lang.T("Слишком большой пакет. Уменьши число отмеченных земель."));if(new[]{"father","mother","real_father","real_mother","clear_father","clear_mother","clear_real_father","clear_real_mother"}.Contains(a.id)){preview+="\r\n\r\n"+await FamilyPreview(p.Character);}if(a.recipients)preview+=Lang.T("\r\n\r\nПорядок: ")+String.Join(" → ",recipientNames)+(a.multi?"\r\n"+String.Join("\r\n",p.Titles.Select((t,i)=>t+" → "+recipientNames[i%recipientNames.Count])):"");var checkTitles=a.multi?p.Titles.Distinct().ToList():new List<string>();if(!a.multi){if(Regex.IsMatch(a.body,@"\$TITLE\b") || a.scope=="title_key")checkTitles.Add(p.Title);if(a.body.Contains("$TITLE2"))checkTitles.Add(p.Title2);}string land=null;if(a.multi){land=await DescribeTitles(p.Titles,p.Character);preview+=Lang.T("\r\n\r\nОтмечено титулов: ")+p.Titles.Count+"\r\n"+land;}
  if(construction!=null)preview+=Lang.T("\r\n\r\nТекущие стройки: ")+construction.Count+"\r\n"+String.Join("\r\n",construction.Select(r=>Lang.T("Провинция ")+r.Province+" → "+r.Key));if(!a.multi && checkTitles.Count>0){land=await DescribeTitles(checkTitles,p.Character);preview+=Lang.T("\r\n\r\nТитулы и текущие владельцы:\r\n")+land;}if(a.id=="inheritance_allocation" && land.Split(new[]{"\r\n"},StringSplitOptions.RemoveEmptyEntries).Any(line=>!line.EndsWith("["+p.Character+"]")))throw new InvalidOperationException(Lang.T("В завещании должны быть титулы, которыми сейчас владеет первый персонаж."));if(a.id=="scenario_split" && p.Titles.Count<p.Recipients.Count)throw new InvalidOperationException(Lang.T("Каждому получателю раскола нужно хотя бы одно графство."));uint siege=0;if(a.native=="siege"){siege=session.Bridge.ProvinceSiege(p.Province);preview+=Lang.T("\r\n\r\nОсада: ")+siege+Lang.T(" · провинция ")+p.Province+Lang.T("\r\nЗавершение ожидается на следующем игровом тике.");}List<OccupationRecord> occupations=null;if(a.native=="occupation"){occupations=await ReadOccupations(p.Character,a.id=="occupation_restore_province"?p.Province:0);if(occupations.Count==0)throw new InvalidOperationException(Lang.T("В выбранном охвате нет оккупированных поселений."));preview+=Lang.T("\r\n\r\nОккупации: ")+occupations.Count+"\r\n"+String.Join("\r\n",occupations.Select(o=>Lang.T("Провинция ")+o.Province+Lang.T(" · оккупант [")+o.Occupant+"]"));}StationRecord station=null;if(a.native=="station"){station=session.Bridge.Station(UInt32.Parse(p.Object.Identity),a.id=="regiment_station"?p.Province:0);preview+=Lang.T("\r\n\r\nРазмещение: ")+(station.Current==0?Lang.T("не назначено"):station.Current.ToString())+" → "+(station.Destination==0?Lang.T("снять"):station.Destination.ToString());}uint culture=0,head=0;if(a.native=="culture_head" || a.native=="culture_head_reset"){culture=session.Bridge.CharacterCulture(p.Character);head=session.Bridge.CultureHead(culture);preview+=Lang.T("\r\n\r\nКультура · внутренний ID: ")+culture+Lang.T("\r\nТекущий глава: ")+(session.Bridge.LivingCharacter(head)?(await session.Inspect(head)).Name+" ["+head+"]":Lang.T("отсутствует"));}return new CampaignPlan{Occupations=occupations,Station=station,CheckTitles=checkTitles,Siege=siege,Culture=culture,PreviousHead=head,Constructions=construction,Action=a,Parameters=p,Player=session.State.Player,GameState=session.Bridge.GameState,Body=body,Preview=preview,Prepared=DateTime.UtcNow,LandFingerprint=land};
 }
 string Wrap(CampaignAction a,CampaignParameters p,string body){if(a.scope=="character")return body;if(a.scope=="province")return "province:"+p.Province+" = { "+body+" }";if(a.scope=="faith" || a.scope=="culture" || a.scope=="domicile")return a.scope+" = { "+body+" }";if(a.scope=="title_key")return "title:"+Key(p.Title)+" = { "+body+" }";return "global_var:ck3t_v3_selected = { "+body+" }";}
 public async Task Execute(CampaignPlan plan){Check();if(plan.Consumed || plan.Player!=session.State.Player || plan.GameState!=session.Bridge.GameState || DateTime.UtcNow-plan.Prepared>TimeSpan.FromMinutes(5))throw new InvalidOperationException(Lang.T("Предпросмотр использован или устарел. Подготовь действие заново."));var a=plan.Action;var p=plan.Parameters;if(p.Object!=null)await Resolve(p.Object,p.Character);if(plan.CheckTitles!=null && plan.CheckTitles.Count>0 && plan.LandFingerprint!=await DescribeTitles(plan.CheckTitles,p.Character))throw new InvalidOperationException(Lang.T("Владельцы отмеченных земель изменились. Подготовь новый предпросмотр."));if(a.body.Contains("$OLD_SIZE")){var current=await RegimentStats(p.Character);if(current[0]!=p.OldSize || current[1]!=p.OldTroops)throw new InvalidOperationException(Lang.T("Размер или численность полка изменились. Подготовь новый предпросмотр."));}if(a.recipients && p.Recipients.Any(id=>!session.Bridge.LivingCharacter(id)))throw new InvalidOperationException(Lang.T("Получатель умер или исчез. Подготовь новый предпросмотр."));if(plan.Constructions!=null)foreach(var c in plan.Constructions){var actual=session.Bridge.Construction(c.Province);if(actual==null || actual.Fingerprint!=c.Fingerprint)throw new InvalidOperationException(Lang.T("Стройка изменилась или завершилась. Обнови предпросмотр."));}if(a.scenario){await CheckScenarioEligibility(a,p.Character);Stories.Preflight(a,p);}plan.Consumed=true;
  try{if(a.native=="occupation"){var fresh=await ReadOccupations(p.Character,a.id=="occupation_restore_province"?p.Province:0);if(!fresh.Select(o=>o.Fingerprint).OrderBy(x=>x).SequenceEqual(plan.Occupations.Select(o=>o.Fingerprint).OrderBy(x=>x)))throw new InvalidOperationException(Lang.T("Оккупации или владельцы изменились; обнови предпросмотр."));foreach(var o in plan.Occupations){var current=session.Bridge.Occupation(o.Province);if(current.Occupant==UInt32.MaxValue)continue;await session.Bridge.ClearOccupation(o,false);}Record(a.title+Lang.T(" · поселений ")+plan.Occupations.Count);return;}if(a.native=="station"){await session.Bridge.ChangeStation(plan.Station,false);Record(a.title+Lang.T(" · полк ")+plan.Station.ID);return;}if(a.native=="siege"){if(session.Bridge.ProvinceSiege(p.Province)!=plan.Siege)throw new InvalidOperationException(Lang.T("Осада изменилась; обнови предпросмотр."));session.Sieges.Complete(plan.Siege);Record(Lang.T("Завершение осады ")+plan.Siege+Lang.T(" · следующий игровой тик"));return;}if(a.native=="culture_head" || a.native=="culture_head_reset"){if(a.native=="culture_head")await session.CultureHeads.Set(plan.Culture,p.Character,plan.PreviousHead);else await session.CultureHeads.Remove(plan.Culture);Record(a.title+Lang.T(" · культура ")+plan.Culture);return;}if(a.native=="war_score" || a.native=="war_score_reset"){uint id=UInt32.Parse(p.Object.Identity);session.Bridge.WarAddress(id);if(a.native=="war_score")session.WarScores.SetOne(id,p.Value);else session.WarScores.Remove(id);Record(a.title+Lang.T(" · война ")+id);return;}await session.Send("set_global_variable = { name = ck3t_v3_player value = this }",session.State.Player);if(a.other)await session.Send("set_global_variable = { name = ck3t_v3_other value = this }",p.Other);
   if(a.recipients)for(int i=0;i<p.Recipients.Count;i++)await session.Send("set_global_variable = { name = ck3t_v3_recipient_"+i+" value = this }",p.Recipients[i]);string command="set_global_variable = { name = ck3t_v3_actor value = this } "+Wrap(a,p,(String.IsNullOrEmpty(a.limit)?plan.Body:"if = { limit = { "+Expand(new CampaignAction{body=a.limit,min=a.min,max=a.max},p)+" } "+plan.Body+" debug_log = \"CK3T_V3_DONE\" }"))+(String.IsNullOrEmpty(a.limit)?" debug_log = \"CK3T_V3_DONE\"":"")+" "+Templates.Flush;
   var r=await SendText(command,p.Character,p);if(!r.Rows("CK3T_V3_DONE").Any() || !String.IsNullOrEmpty(a.successMarker) && !r.Rows(a.successMarker).Any())throw new InvalidOperationException(Lang.T("Условия действия не выполнены; изменение не подтверждено."));if(plan.Constructions!=null && plan.Constructions.Any(c=>session.Bridge.Construction(c.Province)!=null))throw new InvalidOperationException(Lang.T("Не все очереди завершились; проверь журнал и состояние игры перед повтором."));if(a.scenario)await Stories.Start(a,p);Record(a.title+" · "+p.Character);
  }finally{if(a.recipients)await session.Send(String.Join(" ",Enumerable.Range(0,p.Recipients.Count).Select(i=>"remove_global_variable = ck3t_v3_recipient_"+i)),session.State.Player);await session.Send("remove_global_variable = ck3t_v3_actor remove_global_variable = ck3t_v3_other remove_global_variable = ck3t_v3_player remove_global_variable = ck3t_v3_selected",session.State.Player);}
 }
 void Record(string message){History.Add(DateTime.Now.ToString("HH:mm:ss")+" "+message);try{File.AppendAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CK3PersonalTrainer","history.log"),DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+Lang.T(" Редактор: ")+message+Environment.NewLine);}catch(IOException){History.Add(Lang.T("Журнал на диске недоступен; игровая команда уже выполнена."));}}
 public async Task Syntax(CampaignAction a,CampaignParameters p){Check();if(new[]{"war_score","war_score_reset","culture_head","culture_head_reset","siege","station","occupation"}.Contains(a.native))return;string body=Expand(a,p);if(!String.IsNullOrEmpty(a.limit))body="if = { limit = { "+Expand(new CampaignAction{body=a.limit,min=a.min,max=a.max},p)+" } "+body+" }";string wrapped=Iterators.ContainsKey(a.scope)?Iterators[a.scope]+" = { "+body+" }":Wrap(a,p,body);await SendText("set_global_variable = { name = ck3t_v3_player value = this } set_global_variable = { name = ck3t_v3_actor value = this } set_global_variable = { name = ck3t_v3_other value = this } if = { limit = { always = no } "+wrapped+" } remove_global_variable = ck3t_v3_player remove_global_variable = ck3t_v3_actor remove_global_variable = ck3t_v3_other",p.Character,p);}
 public async Task Clear(){Check();string body=String.Join(" ",caches.Select(x=>"clear_global_variable_list = "+x))+" remove_global_variable = ck3t_v3_selected remove_global_variable = ck3t_v3_actor remove_global_variable = ck3t_v3_other remove_global_variable = ck3t_v3_player";await session.Send(body,session.State.Player);caches.Clear();}
 public async Task<string> FamilyPreview(uint person){string root="SCOPE.GetRootScope.GetCharacter";var r=await session.Send("debug_log = \"CK3T_FAMILY|["+root+".GetFather.GetID]|["+root+".GetMother.GetID]|["+root+".GetRealFather.GetID]|["+root+".GetRealMother.GetID]|["+root+".GetHouse.GetNameNoTooltip]\"",person);var row=r.Rows("CK3T_FAMILY|").LastOrDefault();var parts=(row??"").Split('|');if(parts.Length!=5 || parts.Take(4).Any(x=>!Regex.IsMatch(x,@"^\d+$")))throw new InvalidOperationException(Lang.T("Не удалось прочитать родственные связи для предпросмотра."));var labels=new[]{Lang.T("Юридический отец"),Lang.T("Юридическая мать"),Lang.T("Биологический отец"),Lang.T("Биологическая мать")};var lines=new List<string>();for(int i=0;i<4;i++){uint id=UInt32.Parse(parts[i]);lines.Add(labels[i]+": "+(id==0 || id==UInt32.MaxValue?Lang.T("отсутствует"):(await session.Inspect(id)).Name+" ["+id+"]"));}lines.Add(Lang.T("Дом: ")+parts[4]);lines.Add(Lang.T("Изменение связей влияет на происхождение, брачные ограничения и наследование. Уже существующие титулы и претензии автоматически не откатываются."));return String.Join("\r\n",lines);}
 public async Task<List<OccupationRecord>> ReadOccupations(uint actor,uint province){Check();string body="set_global_variable = { name = ck3t_v3_scan_owner value = this } "+Templates.Expand("$PROVINCES{ debug_log = \"CK3T_OCCUPATION_PROVINCE\" debug_log_scopes = no }","ck3t_v3_scan_owner")+" remove_global_variable = ck3t_v3_scan_owner";var r=await session.Send(body,actor);var ids=System.Text.RegularExpressions.Regex.Matches(r.Text,@"Internal ID: (\d+)\).*?\(Province").Cast<System.Text.RegularExpressions.Match>().Select(m=>UInt32.Parse(m.Groups[1].Value)).Distinct().ToList();if(province!=0 && !ids.Contains(province))throw new InvalidOperationException(Lang.T("Провинция вне выбранного охвата владений."));var result=ids.Where(id=>province==0 || id==province).Select(id=>session.Bridge.Occupation(id)).Where(o=>o.Occupant!=UInt32.MaxValue).OrderBy(o=>o.Province).ToList();if(result.Count>100)throw new InvalidOperationException(Lang.T("Более 100 оккупаций. Снимай по провинциям."));return result;}
 public async Task<List<ConstructionRecord>> ReadConstructions(uint actor,uint province){Check();var ids=new List<uint>();if(province!=0)ids.Add(province);else{string body="set_global_variable = { name = ck3t_v3_scan_owner value = this } "+Templates.Expand("$PROVINCES{ if = { limit = { has_ongoing_construction = yes } debug_log = \"CK3T_CONSTRUCTION_PROVINCE\" debug_log_scopes = no } }","ck3t_v3_scan_owner")+" remove_global_variable = ck3t_v3_scan_owner";var reply=await session.Send(body,actor);bool waiting=false;foreach(string line in reply.Text.Split('\n')){if(line.Contains("jomini_effect_impl.cpp") && line.Contains("CK3T_CONSTRUCTION_PROVINCE")){waiting=true;continue;}if(waiting && line.Contains("effectimpl.cpp:642")){var m=Regex.Match(line,@"Internal ID: (\d+)\).*?\(Province");uint id;if(m.Success && UInt32.TryParse(m.Groups[1].Value,out id)){ids.Add(id);waiting=false;}}}}var result=new List<ConstructionRecord>();foreach(uint id in ids.Distinct()){var record=session.Bridge.Construction(id);if(record==null)continue;if(!Catalogs["building"].Any(x=>x.id==record.Key) && !new[]{"castle_holding","city_holding","temple_holding","tribal_holding"}.Contains(record.Key))throw new InvalidOperationException(Lang.T("Не поддерживается очередь: ")+record.Key);result.Add(record);}if(result.Count>100)throw new InvalidOperationException(Lang.T("Найдено более 100 строек. Завершай провинции отдельными пакетами."));return result;}
 public async Task<int[]> RegimentStats(uint actor){var r=await session.Send("global_var:ck3t_v3_selected = { set_global_variable = { name = ck3t_v3_stat_size value = maa_size } set_global_variable = { name = ck3t_v3_stat_troops value = maa_current_troops_count } } debug_log = \"CK3T_REG_STATS|[GetGlobalVariable('ck3t_v3_stat_size').GetValue]|[GetGlobalVariable('ck3t_v3_stat_troops').GetValue]\" remove_global_variable = ck3t_v3_stat_size remove_global_variable = ck3t_v3_stat_troops",actor);string line=r.Rows("CK3T_REG_STATS|").LastOrDefault();var parts=(line??"").Split('|');int size,troops;if(parts.Length!=2 || !Int32.TryParse(parts[0],out size) || !Int32.TryParse(parts[1],out troops) || size<=0 || size>1000 || troops<0)throw new InvalidOperationException(Lang.T("Не удалось прочитать точные параметры полка."));return new[]{size,troops};}
 public async Task<string> DescribeTitles(IEnumerable<string> titles,uint actor){var lines=new List<string>();var all=titles.Distinct().ToList();for(int start=0;start<all.Count;start+=20){var batch=all.Skip(start).Take(20).ToList();string body=String.Join(" ",batch.Select(t=>"title:"+Key(t)+" = { debug_log = \"CK3T_MAP_TITLE\" debug_log_scopes = no if = { limit = { exists = holder } holder = { debug_log = \"CK3T_MAP_HOLDER_"+t+"\" debug_log_scopes = no } } else = { debug_log = \"CK3T_MAP_UNHELD_"+t+"\" } }"));var r=await session.Send(body,actor);var read=ParseObjects(r.Text,"title","","CK3T_MAP_TITLE");if(read.Count!=batch.Count || !read.Select(o=>o.Key).OrderBy(k=>k).SequenceEqual(batch.OrderBy(k=>k)))throw new InvalidOperationException(Lang.T("Предпросмотр не прочитал все выбранные титулы. Передача отменена."));foreach(var t in read){var holders=ParseObjects(r.Text,"person","","CK3T_MAP_HOLDER_"+t.Key);bool unheld=r.Rows("CK3T_MAP_UNHELD_"+t.Key).Any();if(holders.Count!=1 && !(holders.Count==0 && unheld))throw new InvalidOperationException(Lang.T("Не удалось проверить владельца: ")+t.Key);lines.Add(t.Key+" · "+t.Name+" → "+(unheld?Lang.T("без владельца"):holders[0].Name+" ["+holders[0].Identity+"]"));}}return String.Join("\r\n",lines.OrderBy(l=>l,StringComparer.Ordinal));}
 public async Task<List<string>> SelectLand(string mode,uint actor,string key){Check();if(!new[]{"realm","border","faith","culture"}.Contains(mode))throw new InvalidOperationException(Lang.T("Неизвестная выборка земель."));string iterator=mode=="border"?"every_realm_border_county":mode=="faith"?"faith:"+Key(key)+" = { every_faith_county":mode=="culture"?"culture:"+Key(key)+" = { every_culture_county":"every_sub_realm_county";string body=iterator+" = { debug_log = \"CK3T_MAP_TITLE\" debug_log_scopes = no }"+(mode=="faith" || mode=="culture"?" }":"");var r=await session.Send(body,actor);return ParseObjects(r.Text,"title","","CK3T_MAP_TITLE").Select(t=>t.Key).Where(t=>Catalogs["title"].Any(x=>x.id==t)).Distinct().ToList();}
}
